import{_ as t,o,c as d,a2 as a}from"./chunks/framework.E8pQZ6KS.js";const p=JSON.parse('{"title":"Linux 与命令行","description":"","frontmatter":{},"headers":[],"relativePath":"必学工具/Linux.md","filePath":"必学工具/Linux.md","lastUpdated":1792430298000}'),r={name:"必学工具/Linux.md"};function c(i,e,l,n,s,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="linux-与命令行" tabindex="-1">Linux 与命令行 <a class="header-anchor" href="#linux-与命令行" aria-label="Permalink to &quot;Linux 与命令行&quot;">​</a></h1><blockquote><p>网络安全从业者的第一生产力。攻防两端的工作几乎都发生在 Linux 环境（服务器、靶场、Kali、云主机），不会命令行等于没有手。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>主流安全工具（Nmap、Metasploit、Burp、Wireshark、GDB 等）的原生环境都是 Linux；</li><li>渗透测试、运维排查、日志分析的核心场景全在终端；</li><li>学校课程（操作系统及安全、网络攻防技术）的实验环境大量使用 Linux。</li></ul><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><ol><li><strong>装一个 Linux</strong>：推荐先装虚拟机里的 Ubuntu Desktop（见 <a href="./虚拟机与Kali.html">虚拟机与 Kali</a>），别怕折腾；</li><li><strong>过一遍命令行基础</strong>：文件系统、权限、进程、管道、重定向、常用命令（<code>ls</code> <code>cd</code> <code>grep</code> <code>find</code> <code>ps</code> <code>netstat</code> <code>ssh</code> <code>scp</code> 等）；</li><li><strong>会写 Shell 脚本</strong>：把重复操作脚本化。</li></ol><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《鸟哥的 Linux 私房菜》</td><td>书</td><td>中文 Linux 经典入门，基础篇足够</td></tr><tr><td><a href="https://linuxjourney.com/" target="_blank" rel="noreferrer">Linux Journey</a></td><td>网站</td><td>交互式入门教程，节奏友好</td></tr><tr><td><a href="https://missing.csail.mit.edu/" target="_blank" rel="noreferrer">missing-semester（MIT）</a></td><td>公开课</td><td>「命令行 + 编辑器 + 版本控制」一网打尽，中文翻译在 <a href="https://missing-semester-cn.github.io/" target="_blank" rel="noreferrer">missing-semester-cn</a></td></tr><tr><td><a href="https://overthewire.org/wargames/bandit/" target="_blank" rel="noreferrer">OverTheWire: Bandit</a></td><td>闯关</td><td>用游戏方式练 SSH 与命令行</td></tr></tbody></table><h2 id="核心技能清单" tabindex="-1">核心技能清单 <a class="header-anchor" href="#核心技能清单" aria-label="Permalink to &quot;核心技能清单&quot;">​</a></h2><ul><li>文件与权限：<code>chmod</code> / <code>chown</code> / 软硬链接</li><li>文本处理：<code>grep</code> / <code>awk</code> / <code>sed</code> / <code>cut</code> / <code>sort</code> / <code>uniq</code></li><li>进程与端口：<code>ps</code> / <code>top</code> / <code>netstat</code> / <code>ss</code> / <code>lsof</code></li><li>网络：<code>ssh</code> / <code>scp</code> / <code>curl</code> / <code>wget</code> / <code>nc</code>（netcat）</li><li>日志：<code>/var/log</code> 常见日志、<code>tail -f</code>、<code>journalctl</code></li></ul><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li><strong>别背命令</strong>，遇到就查 <code>man</code> / <code>--help</code> / <code>tldr</code>；</li><li>把「折腾环境」当学习本身：装坏一次系统，就多会一点；</li><li>大二前把基础过完，大三学攻防时直接进入战斗状态。</li></ul>',12)])])}const m=t(r,[["render",c]]);export{p as __pageData,m as default};
